std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.vertices_begin(); vit != rt.vertices_end(); ++vit) {
    if (rt.is_infinite(vit)) continue;

    const auto& wp = vit->point();
    const auto& pt = wp.point();
    const double m = vit->info().mass;
    const double a = vit->info().a;
    const double b = vit->info().b;
    const double c = vit->info().c;

    const double x = pt.x() + time * a;
    const double y = pt.y() + time * b;
    const double z = pt.z() + time * c;

    Node node;
    node.position = Point_3(x, y, z);
    node.velocity = Vector_3(a, b, c);
    node.mass = m;

    bool is_multinode = false;
    std::vector<RT::Vertex_handle> neighbors;
    rt.adjacent_vertices(vit, std::back_inserter(neighbors));

    for (const auto& neighbor : neighbors) {
        if (rt.is_infinite(neighbor)) continue;
        const double neighbor_m = neighbor->info().mass;
        const double total_m = m + neighbor_m;
        if (total_m > threshold) {
            is_multinode = true;
            break;
        }
    }

    node.type = is_multinode ? NodeType::MULTI : NodeType::SINGLE;
    nodes.push_back(std::move(node));
}

return nodes;
// END_CODE

